using System;using System.IO;using System.Threading;using System.Windows.Forms;using Windows.ApplicationModel.Calls;
[assembly:System.Reflection.AssemblyFileVersion("0.1.0.17")]
static class Probe {
 static string log="";static void Record(string s){log+=s+Environment.NewLine;var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"PhoneDeck");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"native-lines.local.txt"),log);}
 static void Wait(Func<Windows.Foundation.AsyncStatus> f){var end=DateTime.UtcNow.AddSeconds(10);while(f()==Windows.Foundation.AsyncStatus.Started&&DateTime.UtcNow<end){Application.DoEvents();Thread.Sleep(30);}if(f()!=Windows.Foundation.AsyncStatus.Completed)throw new Exception("AsyncStatus="+f());}
 [STAThread]static void Main(){try{foreach(var t in new[]{typeof(PhoneLine),typeof(PhoneCallStore),typeof(PhoneCallManager)})foreach(var m in t.GetMethods())if(m.DeclaringType==t)Record(t.Name+"."+m);var op=PhoneCallManager.RequestStoreAsync();Wait(()=>op.Status);var store=op.GetResults();Record("Store="+(store!=null));var def=store.GetDefaultLineAsync();Wait(()=>def.Status);Record("HasDefaultLine="+(def.GetResults()!=Guid.Empty));var watcher=store.RequestLineWatcher();int count=0;bool done=false;watcher.LineAdded+=(o,e)=>{count++;try{var lineOp=PhoneLine.FromIdAsync(e.LineId);Wait(()=>lineOp.Status);var line=lineOp.GetResults();Record("LineFound="+count+";Transport="+line.Transport+";CanDial="+line.CanDial+";Network="+line.NetworkState);}catch(Exception ex){Record("LineReadError="+ex.HResult.ToString("X8"));}};watcher.EnumerationCompleted+=(o,e)=>{done=true;};watcher.Start();var deadline=DateTime.UtcNow.AddSeconds(8);while(!done&&DateTime.UtcNow<deadline){Application.DoEvents();Thread.Sleep(30);}watcher.Stop();Record("Lines="+count+";EnumerationCompleted="+done);Record("No call or connection actions performed.");}catch(Exception e){Record("Error="+e.HResult.ToString("X8")+";"+e.Message);}}
}